using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
namespace PinPop {
 public sealed class PopupCloseReview:MonoBehaviour {
  [Serializable]class Saved {public string key,value;public bool integer,exists;}
  [Serializable]class Report {public int passed,failed;public bool complete,restored;public List<string> checks=new List<string>();}
  public static bool Active {get;private set;}
  readonly List<Saved> saved=new List<Saved>();Report report=new Report();PinPopGame game;EventSystem events;bool eventsEnabled,restored;string folder;RenderTexture screen;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){string request=Path.Combine(Application.persistentDataPath,"PopupCloseReview.request");if(Array.IndexOf(Environment.GetCommandLineArgs(),"-popup-close-test")<0&&!File.Exists(request))return;if(File.Exists(request))File.Delete(request);Active=true;new GameObject("Popup close review").AddComponent<PopupCloseReview>();}
  void Check(bool ok,string detail){if(ok)report.passed++;else report.failed++;report.checks.Add((ok?"PASS: ":"FAIL: ")+detail);Debug.Log(report.checks[report.checks.Count-1]);Save();}
  void Remember(string key,bool integer){saved.Add(new Saved{key=key,integer=integer,exists=PlayerPrefs.HasKey(key),value=integer?PlayerPrefs.GetInt(key).ToString():PlayerPrefs.GetString(key)});}
  IEnumerator Start(){
   folder=Environment.GetEnvironmentVariable("PINPOP_QA_DIR")??Path.Combine(Application.persistentDataPath,"PopupCloseReview");Directory.CreateDirectory(folder);Application.logMessageReceived+=Log;
   while((game=FindFirstObjectByType<PinPopGame>())==null||!game.Initialized||PinPopSplash.Visible)yield return null;
   events=EventSystem.current;eventsEnabled=events.enabled;events.enabled=false;
   foreach(string key in new[]{PinPopEconomy.SaveKey,PinPopAdventure.SaveKey,GameLocalization.PreferenceKey})Remember(key,false);foreach(string key in new[]{"Level","Coins","SwapCredits","ReducedMotion","Muted",PinPopHUD.TutorialSeenKey})Remember(key,true);
   string language=Environment.GetEnvironmentVariable("PINPOP_REVIEW_LANGUAGE");GameLocalization.SetPreference(language=="en"?"en":"tr");CrispUI.ReviewReducedMotion=true;PlayerPrefs.SetInt(PinPopHUD.TutorialSeenKey,1);
   PlayerPrefs.SetInt("Level",0);new PinPopEconomy(new EconomySave{coins=300,swaps=3,highestLevel=40}).Save();PlayerPrefs.SetString(PinPopAdventure.SaveKey,JsonUtility.ToJson(new AdventureSave{lessons=511}));game.ReloadEconomy();game.Adventure.Reload();
   foreach(var size in new[]{new Vector2Int(320,568),new Vector2Int(390,844),new Vector2Int(1170,2532)}){
    Size(size.x,size.y);Board(11);yield return new WaitForSecondsRealtime(.3f);
    foreach(bool home in new[]{true,false}){
     game.SetMenu(home);if(home)game.Hud.ShowHome();else game.Hud.ShowGame();game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.2f);Inspect("CLOSE_SETTINGS","Settings card","settings "+home);Snapshot state=new Snapshot(game);Check(Click("CLOSE_SETTINGS"),"Settings cross receives pointer");Check(!game.Hud.SettingsVisible&&!game.Paused&&state.Same(game),"Settings cross preserves gameplay and wallet");
     game.Hud.ShowShop();yield return new WaitForSecondsRealtime(.2f);Inspect("CLOSE_SHOP","Catalog border","shop "+home);Check(GameObject.Find("CLOSE_SHOP").GetComponentsInChildren<Text>().Length==0,"Shop cross has no bottom Close label");Capture("shop-"+(home?"home":"game")+"-"+size.x);state=new Snapshot(game);Click("CLOSE_SHOP");Check(!game.Hud.ShopVisible&&!game.Paused&&state.Same(game),"Shop cross returns without spending or changing selection");
    }
    game.Hud.ShowSwapShop();yield return new WaitForSecondsRealtime(.2f);Inspect("SWAP_BUY_CANCEL","Swap border","swap purchase");Check(GameObject.Find("SWAP_BUY_CONFIRM")!=null,"Swap purchase retains its Buy action");Snapshot swapState=new Snapshot(game);Capture("swap-"+size.x);Click("SWAP_BUY_CANCEL");Check(!game.Hud.SwapShopVisible&&!game.Paused&&swapState.Same(game),"Swap cross cancels without buying or rotating the queue");
    var adventure=game.GetComponent<AdventureHUD>();for(int id=0;id<4;id++){adventure.ShowBooster(id);yield return new WaitForSecondsRealtime(.2f);Inspect("ADVENTURE_CLOSE","Adventure card","helper "+id);Check(GameObject.Find("BOOSTER_BUY")!=null,"Helper retains its purchase action");Snapshot state=new Snapshot(game);if(id==1||id==3)Check(GameObject.Find("BOOSTER_USE")!=null,"Helper retains Use");Capture("helper-"+id+"-"+size.x);Click("ADVENTURE_CLOSE");Check(!adventure.ModalVisible&&!game.Paused&&state.Same(game),"Helper cross preserves stock, moves and wallet");}
    foreach(int focus in new[]{0,20}){adventure.ShowMap();yield return new WaitForSecondsRealtime(.2f);if(focus==0){Click("MAP_REGION_0");yield return new WaitForSecondsRealtime(.2f);}Inspect("ADVENTURE_CLOSE","Adventure card","map "+focus);Snapshot state=new Snapshot(game);Capture("map-"+focus+"-"+size.x);Click("ADVENTURE_CLOSE");Check(!adventure.ModalVisible&&!game.Paused&&state.Same(game),"Map cross preserves progress and wallet");}
    game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.15f);Click("HELP_SETTINGS");yield return new WaitForSecondsRealtime(.25f);Inspect("HELP_CLOSE","Animated help card","how-to");Capture("help-"+size.x);Click("HELP_CLOSE");Check(game.Hud.SettingsVisible&&game.Paused,"How-to cross returns to paused settings");game.Hud.CloseOverlays();
    var showLesson=typeof(AdventureHUD).GetMethod("PresentLesson",BindingFlags.Instance|BindingFlags.NonPublic);foreach(string title in new[]{"SEKME ENGELLERİ","BUZLU DUBA","BAĞLI ÜÇLÜ","HAREKETLİ BARİYER","NEW CHARACTER"}){showLesson.Invoke(adventure,new object[]{title+"\n"+GameLocalization.Text("Aynı renkleri üçle")});yield return new WaitForSecondsRealtime(.2f);Inspect("ADVENTURE_CLOSE","Adventure card","lesson "+title);Snapshot state=new Snapshot(game);Click("ADVENTURE_CLOSE");Check(!adventure.ModalVisible&&!game.Paused&&state.Same(game),"Lesson cross closes without an extra Got It action");}
    foreach(int level in new[]{0,4,39}){Board(level);Win();yield return new WaitForSecondsRealtime(.25f);Inspect("RESULT_HOME","Victory border","victory "+level);Check(GameObject.Find("CONTINUE")!=null,"Victory retains Continue");Capture("victory-"+level+"-"+size.x);int coins=game.Coins,swaps=game.SwapCredits;Click("RESULT_HOME");Check(game.InMenu&&game.Hud.HomeVisible&&!game.Hud.ResultVisible&&game.Coins==coins&&game.SwapCredits==swaps,"Victory cross returns home without paying a duplicate reward");}
    foreach(string kind in new[]{"fresh","used-video","overflow","unavailable"}){Board(11);typeof(PinPopGame).GetProperty("Moves").SetValue(game,0);if(kind=="used-video")typeof(PinPopGame).GetProperty("VideoRescueUsed").SetValue(game,true);if(kind=="overflow")typeof(PinPopGame).GetProperty("TrayOverflow").SetValue(game,true);game.SendMessage("End",false);if(kind=="unavailable")game.Hud.RecoveryMessage("Video şu an hazır değil. Biraz sonra tekrar dene.");yield return new WaitForSecondsRealtime(.2f);Inspect("RESULT_HOME","Recovery border","failure "+kind);Check(GameObject.Find("CONTINUE")!=null,"Failure retains Retry");Capture("failure-"+kind+"-"+size.x);int coins=game.Coins;Click("RESULT_HOME");Check(game.InMenu&&game.Hud.HomeVisible&&!game.Finished&&game.Coins==coins,"Failure cross returns to a playable home state");}
   }
   // Cancel the owned preparation panel before SDK startup can begin on a device.
   Size(Screen.width,Screen.height);Board(0);typeof(PinPopGame).GetProperty("Moves").SetValue(game,0);game.SendMessage("End",false);yield return new WaitForSecondsRealtime(.3f);int balance=game.Coins,attempt=game.AttemptId;game.RewardedVideo.Watch();Canvas.ForceUpdateCanvases();var video=GameObject.Find("Cancel rewarded video");Check(video!=null&&video.GetComponentsInChildren<Text>().Length==0&&video.GetComponentInChildren<CrispIcon>().Symbol==CrispIcon.Kind.Close,"Owned video panel has a cross and no bottom Cancel button");Check(!GameObject.Find("RESULT_HOME").GetComponent<Button>().interactable,"Result cross stays disabled while a reward request is active");var videoCanvas=video.GetComponentInParent<Canvas>();var previousMode=videoCanvas.renderMode;var videoNodes=videoCanvas.GetComponentsInChildren<Transform>(true);var oldLayers=new int[videoNodes.Length];for(int i=0;i<videoNodes.Length;i++){oldLayers[i]=videoNodes[i].gameObject.layer;videoNodes[i].gameObject.layer=5;}videoCanvas.renderMode=RenderMode.ScreenSpaceCamera;videoCanvas.worldCamera=game.Hud.UICamera;videoCanvas.planeDistance=.5f;Canvas.ForceUpdateCanvases();Capture("video-preparation");videoCanvas.renderMode=previousMode;for(int i=0;i<videoNodes.Length;i++)videoNodes[i].gameObject.layer=oldLayers[i];Canvas.ForceUpdateCanvases();Check(Click("Cancel rewarded video"),"Video preparation cross receives pointer");Check(!game.RewardedVideo.Busy&&game.Finished&&!game.VideoRescueUsed&&game.Moves==0&&game.Coins==balance&&game.AttemptId==attempt,"Preparation cancellation grants no reward and preserves retry eligibility");Check(GameObject.Find("RESULT_HOME").GetComponent<Button>().interactable,"Result cross becomes available after cancellation");Click("RESULT_HOME");
   Restore();report.complete=true;Active=false;events.enabled=eventsEnabled;Save();Application.Quit(report.failed==0?0:1);
  }
  sealed class Snapshot {readonly int coins,moves,swaps,attempt,selected;readonly int[] queue,stock;public Snapshot(PinPopGame g){coins=g.Coins;moves=g.Moves;swaps=g.SwapCredits;attempt=g.AttemptId;selected=g.SelectedBall;queue=g.Queue.ToArray();stock=(int[])g.Adventure.Data.stock.Clone();}public bool Same(PinPopGame g){if(coins!=g.Coins||moves!=g.Moves||swaps!=g.SwapCredits||attempt!=g.AttemptId||selected!=g.SelectedBall||queue.Length!=g.Queue.Count)return false;for(int i=0;i<queue.Length;i++)if(queue[i]!=g.Queue[i])return false;for(int i=0;i<4;i++)if(stock[i]!=g.Adventure.Data.stock[i])return false;return true;}}
  void Inspect(string closeName,string cardName,string context){Canvas.ForceUpdateCanvases();var close=GameObject.Find(closeName).GetComponent<Button>();var card=GameObject.Find(cardName).GetComponent<RectTransform>();var root=card.parent;int crosses=0;bool noLabels=true;foreach(var b in root.GetComponentsInChildren<Button>()){foreach(var icon in b.GetComponentsInChildren<CrispIcon>())if(icon.Symbol==CrispIcon.Kind.Close)crosses++;foreach(var label in b.GetComponentsInChildren<Text>()){string text=label.text.Trim().ToUpperInvariant();noLabels&=text!="KAPAT"&&text!="VAZGEÇ"&&text!="TAMAM"&&text!="ANLADIM"&&text!="CLOSE"&&text!="CANCEL"&&text!="DONE"&&text!="GOT IT";}}Check(crosses==1&&noLabels,"Exactly one cross and no text dismiss action: "+context);var area=Bounds(card);var art=Bounds(close.targetGraphic.rectTransform);Check(art.center.x>area.center.x&&art.center.y>area.center.y&&art.xMax<=area.xMax+1&&art.yMax<=area.yMax+1,"Cross sits inside the top-right card corner: "+context);var hit=Bounds(close.GetComponent<RectTransform>());float logicalScale=game.GetComponent<HtmlReferenceHUD>().AppRect.width/390;Check(hit.width/logicalScale>=43.9f&&hit.height/logicalScale>=43.9f,"Cross has a stable touch target: "+context);foreach(var title in root.GetComponentsInChildren<Text>())if(title.name=="Victory title"||title.name=="Recovery title"||title.name=="Catalog title"||title.name=="Swap title")Check(title.preferredHeight<=title.rectTransform.rect.height+1,"Header fits beside cross: "+context);}
  void Board(int level){game.GetComponent<AdventureHUD>().Close();game.Hud.HideResult();game.Hud.CloseOverlays();game.SetMenu(false);game.LoadLevel(level);game.Hud.ShowGame();}
  void Win(){typeof(PinPopGame).GetProperty("Cleared").SetValue(game,game.Total);game.SendMessage("End",true);}
  Rect Bounds(RectTransform rect){var c=new Vector3[4];rect.GetWorldCorners(c);var canvas=rect.GetComponentInParent<Canvas>();var camera=canvas!=null&&canvas.renderMode==RenderMode.ScreenSpaceOverlay?null:game.Hud.UICamera;var a=RectTransformUtility.WorldToScreenPoint(camera,c[0]);var b=RectTransformUtility.WorldToScreenPoint(camera,c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
  bool Click(string name){Canvas.ForceUpdateCanvases();var expected=GameObject.Find(name);if(expected==null){Check(false,"Missing action: "+name);return false;}var pointer=new PointerEventData(events){position=Bounds(expected.GetComponent<RectTransform>()).center,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();events.RaycastAll(pointer,hits);var target=hits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject);Check(target==expected,"Pointer reaches "+name);if(target==expected)ExecuteEvents.Execute(target,pointer,ExecuteEvents.pointerClickHandler);return target==expected;}
  void Size(int w,int h){CrispUI.ReviewSize=new Vector2Int(w,h);CrispUI.ReviewSafeArea=w==1170?new Rect(0,102,w,h-243):new Rect(0,0,w,h);if(screen!=null){screen.Release();Destroy(screen);}screen=new RenderTexture(w,h,24);screen.Create();game.Camera.targetTexture=screen;game.Hud.UICamera.targetTexture=screen;}
  void Capture(string name){Canvas.ForceUpdateCanvases();var old=RenderTexture.active;game.Camera.Render();game.Hud.UICamera.Render();RenderTexture.active=screen;var tex=new Texture2D(screen.width,screen.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,screen.width,screen.height),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),tex.EncodeToPNG());Destroy(tex);RenderTexture.active=old;}
  void Log(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){Check(false,message+"\n"+stack);Restore();Save();Application.Quit(1);}}
  void Save(){File.WriteAllText(Path.Combine(folder,"verification.json"),JsonUtility.ToJson(report,true));}
  void Restore(){if(restored)return;restored=true;foreach(var value in saved){if(!value.exists)PlayerPrefs.DeleteKey(value.key);else if(value.integer)PlayerPrefs.SetInt(value.key,int.Parse(value.value));else PlayerPrefs.SetString(value.key,value.value);}PlayerPrefs.Save();report.restored=true;}
  void OnApplicationQuit(){Restore();}void OnDestroy(){Active=false;if(events!=null)events.enabled=eventsEnabled;Application.logMessageReceived-=Log;Restore();CrispUI.ReviewSize=null;CrispUI.ReviewSafeArea=null;}
 }
}
